const files = $input.all();
const allowed = new Set([
  'image/jpeg',
  'image/jpg',
  'image/png',
  'image/webp',
  'image/heic',
  'image/heif',
  'application/pdf'
]);

return files
  .filter(item => {
    const mime = String(item.json.mimeType || '').toLowerCase();
    const name = String(item.json.name || '').toLowerCase();
    return allowed.has(mime) || /\.(jpg|jpeg|png|webp|heic|heif|pdf)$/i.test(name);
  })
  .map(item => ({
    json: {
      file_id: item.json.id,
      file_name: item.json.name || 'unknown-file',
      mime_type: item.json.mimeType || 'application/octet-stream',
      created_time: item.json.createdTime || '',
      modified_time: item.json.modifiedTime || '',
      web_view_link: item.json.webViewLink || `https://drive.google.com/file/d/${item.json.id}/view`,
      processed_at: new Date().toISOString()
    }
  }));

const processed = $('Google Sheets: Đọc File Đã Xử Lý').all();
const processedIds = new Set(
  processed
    .map(r => String((r.json && r.json['File ID']) ?? '').trim())
    .filter(Boolean)
);

const files = $('Lọc File Ảnh/PDF Hóa Đơn').all();
const newFiles = files.filter(f => {
  const id = String(f.json.file_id ?? '').trim();
  return id && !processedIds.has(id);
});

// Chỉ chuyển tiếp file CHƯA có trong sheet (theo cột File ID).
// Nếu tất cả đã xử lý -> trả mảng rỗng -> workflow dừng tại đây.
return newFiles.map(f => ({ json: f.json }));

const sources = $('Lọc File Chưa Xử Lý').all();
const items = $input.all();

const prompt = `Bạn là hệ thống OCR Vision cho phòng kế toán doanh nghiệp Việt Nam.
Nhiệm vụ: đọc ảnh/PDF hóa đơn, biên nhận, phiếu thu, phiếu chi, hóa đơn VAT, hóa đơn bán lẻ hoặc hóa đơn dịch vụ.

Chỉ trả về JSON hợp lệ, không markdown, không giải thích. Nếu trường nào không nhìn thấy rõ thì trả chuỗi rỗng hoặc null, không bịa dữ liệu.

Schema bắt buộc:
{
  "document_type": "invoice|receipt|bill|payment_slip|other",
  "invoice_number": "",
  "invoice_date": "YYYY-MM-DD hoặc chuỗi gốc nếu không chắc",
  "seller_name": "",
  "seller_tax_id": "",
  "seller_address": "",
  "buyer_name": "",
  "buyer_tax_id": "",
  "currency": "VND|USD|...",
  "subtotal": 0,
  "vat_amount": 0,
  "discount_amount": 0,
  "total_amount": 0,
  "payment_method": "cash|bank_transfer|card|e_wallet|unknown",
  "line_items": [
    {
      "description": "",
      "quantity": 0,
      "unit_price": 0,
      "amount": 0
    }
  ],
  "confidence": 0,
  "summary_vi": "Tóm tắt ngắn bằng tiếng Việt",
  "needs_manual_review": false,
  "manual_review_reason": ""
}

Quy tắc:
- Chuẩn hóa số tiền về number, bỏ dấu chấm/phẩy phân tách nghìn.
- Nếu tổng tiền có nhiều dòng, ưu tiên dòng Tổng cộng/Thanh toán/Total.
- confidence từ 0 đến 1 dựa trên độ rõ của ảnh và độ chắc chắn khi đọc.
- needs_manual_review=true nếu ảnh mờ, thiếu tổng tiền, thiếu nhà cung cấp, hoặc confidence < 0.75.`;

const out = [];
for (let i = 0; i < items.length; i++) {
  const source = sources[i]?.json || {};
  const binary = items[i].binary?.data;

  if (!binary) {
    throw new Error(`Không có binary cho file ${source.file_name || '(không rõ)'} (item ${i}). Kiểm tra quyền Google Drive hoặc loại file.`);
  }

  // n8n khuyến nghị dùng helper này thay vì đọc trực tiếp binary.data.data,
  // vì Community/self-hosted có thể lưu binary trên filesystem hoặc external storage.
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  if (!buffer?.length) {
    throw new Error(`Không đọc được binary buffer cho file ${source.file_name || '(không rõ)'} (item ${i}).`);
  }

  const mimeType = binary.mimeType || source.mime_type || 'image/jpeg';
  const base64Data = buffer.toString('base64');

  out.push({
    json: {
      ...source,
      binary_mime_type: mimeType,
      gemini_model: String($('Cấu Hình').first().json.gemini_model || 'gemini-2.5-flash'),
      high_value_threshold: Number($('Cấu Hình').first().json.high_value_threshold || 10000000),
      gemini_request: {
        contents: [
          {
            role: 'user',
            parts: [
              { text: prompt },
              {
                inlineData: {
                  mimeType,
                  data: base64Data
                }
              }
            ]
          }
        ],
        generationConfig: {
          temperature: 0.1,
          maxOutputTokens: 8192,
          responseMimeType: 'application/json'
        }
      }
    },
    pairedItem: { item: i }
  });
}

return out;

function parseJson(text) {
  const clean = String(text)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  return JSON.parse(clean);
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return 0;
  if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
  const normalized = String(value).replace(/[^0-9,.-]/g, '').replace(/[,.](?=\d{3}(\D|$))/g, '').replace(',', '.');
  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : 0;
}

function arr(value) { return Array.isArray(value) ? value : []; }

function esc(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function toIsoDate(value) {
  const s = String(value || '').trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : '';
}

function bucketConfidence(c) {
  if (c < 0.5) return '1. <0.5';
  if (c < 0.75) return '2. 0.5-0.75';
  if (c < 0.9) return '3. 0.75-0.9';
  return '4. >=0.9';
}

function ymOf(d) { return d.slice(0, 7); }
function quarterOf(d) { return `${d.slice(0,4)}-Q${Math.ceil(Number(d.slice(5,7)) / 3)}`; }

const cfg = $('Cấu Hình').first().json;
const usdToVnd = Number(cfg.usd_to_vnd) || 25000;

function toVnd(amount, cur) {
  const c = String(cur || 'VND').toUpperCase();
  if (c === 'VND' || c === '') return amount;
  if (c === 'USD') return Math.round(amount * usdToVnd);
  return ''; // tiền tệ khác: cần tỉ giá riêng -> để trống để không poison tổng VND
}

function blankRow(source, extra) {
  const today = new Date().toISOString().slice(0, 10);
  const base = {
    'Processed At': new Date().toISOString(),
    'File Name': source.file_name || '',
    'File ID': source.file_id || '',
    'File Link': source.web_view_link || '',
    'Document Type': '',
    'Invoice Number': '',
    'Invoice Date': '',
    'Invoice Date ISO': '',
    'Year Month': ymOf(today),
    'Quarter': quarterOf(today),
    'Seller Name': '',
    'Vendor Canonical': '',
    'Seller Tax ID': '',
    'Seller Address': '',
    'Buyer Name': '',
    'Buyer Tax ID': '',
    'Currency': '',
    'Subtotal': 0,
    'VAT Amount': 0,
    'Discount Amount': 0,
    'Total Amount': 0,
    'Total Amount VND': '',
    'Payment Method': '',
    'Line Items JSON': '[]',
    'Confidence': 0,
    'Confidence Bucket': '1. <0.5',
    'Needs Manual Review': true,
    'Manual Review Reason': '',
    'High Value': false,
    'Status': 'ocr_failed',
    'Summary': '',
    'Gemini Model': source.gemini_model || '',
    'Raw OCR JSON': ''
  };
  return Object.assign(base, extra || {});
}

const responses = $input.all();
const sources = $('Tạo Gemini Vision OCR Request').all();

return responses.map((respItem, i) => {
  const source = sources[i]?.json || {};

  try {
    const response = respItem.json;
    if (response && response.error) {
      throw new Error(`Gemini trả lỗi: ${JSON.stringify(response.error).slice(0, 300)}`);
    }
    const rawText = response?.candidates?.[0]?.content?.parts?.[0]?.text || '';
    if (!rawText) {
      throw new Error(`Gemini không trả text. Raw response: ${JSON.stringify(response).slice(0, 300)}`);
    }

    let ocr;
    try { ocr = parseJson(rawText); }
    catch (parseError) { throw new Error(`Không parse được JSON OCR: ${parseError.message}. Text: ${rawText.slice(0, 400)}`); }

    const totalAmount = toNumber(ocr.total_amount);
    const subtotal = toNumber(ocr.subtotal);
    const vatAmount = toNumber(ocr.vat_amount);
    const discountAmount = toNumber(ocr.discount_amount);
    const threshold = toNumber(source.high_value_threshold) || 10000000;
    const confidence = Math.max(0, Math.min(1, Number(ocr.confidence) || 0));
    const isHighValue = totalAmount > threshold;
    const needsManualReview = Boolean(ocr.needs_manual_review) || confidence < 0.75 || !totalAmount || !ocr.seller_name;

    const lineItems = arr(ocr.line_items).map(it => ({
      description: String(it.description || ''),
      quantity: toNumber(it.quantity),
      unit_price: toNumber(it.unit_price),
      amount: toNumber(it.amount)
    }));

    const currency = ocr.currency || 'VND';
    const invoiceDateIso = toIsoDate(ocr.invoice_date);
    const bucketBase = invoiceDateIso || new Date().toISOString().slice(0, 10);
    const totalAmountVnd = toVnd(totalAmount, currency);
    const vendorCanonical = String(ocr.seller_name || '').replace(/\s+/g, ' ').trim();
    const status = needsManualReview ? 'manual_review' : 'processed';

    const anomalyTxnThreshold = Number(cfg.anomaly_txn_threshold) || 30000000;
    const txnVnd = Number(totalAmountVnd) || 0;
    const isTxnAnomaly = txnVnd > anomalyTxnThreshold;
    const todayIso = new Date().toISOString().slice(0, 10);
    const txnDeltaPct = anomalyTxnThreshold > 0 ? Math.round(((txnVnd - anomalyTxnThreshold) / anomalyTxnThreshold) * 100) : 0;
    const anomalyRow = isTxnAnomaly ? {
      'Date': todayIso,
      'Period': ymOf(bucketBase),
      'Metric': 'Giao dịch lớn',
      'Value VND': txnVnd,
      'Baseline VND': anomalyTxnThreshold,
      'Delta %': txnDeltaPct,
      'Severity': txnVnd >= anomalyTxnThreshold * 2 ? 'HIGH' : 'MEDIUM',
      'Note': `Hóa đơn ${ocr.invoice_number || '(không số)'} từ ${vendorCanonical || '(không rõ)'} = ${txnVnd.toLocaleString('vi-VN')} VND vượt ngưỡng giao dịch lớn ${anomalyTxnThreshold.toLocaleString('vi-VN')} VND.`
    } : null;

    const row = {
      'Processed At': new Date().toISOString(),
      'File Name': source.file_name || '',
      'File ID': source.file_id || '',
      'File Link': source.web_view_link || '',
      'Document Type': ocr.document_type || 'other',
      'Invoice Number': ocr.invoice_number || '',
      'Invoice Date': ocr.invoice_date || '',
      'Invoice Date ISO': invoiceDateIso,
      'Year Month': ymOf(bucketBase),
      'Quarter': quarterOf(bucketBase),
      'Seller Name': ocr.seller_name || '',
      'Vendor Canonical': vendorCanonical,
      'Seller Tax ID': ocr.seller_tax_id || '',
      'Seller Address': ocr.seller_address || '',
      'Buyer Name': ocr.buyer_name || '',
      'Buyer Tax ID': ocr.buyer_tax_id || '',
      'Currency': currency,
      'Subtotal': subtotal,
      'VAT Amount': vatAmount,
      'Discount Amount': discountAmount,
      'Total Amount': totalAmount,
      'Total Amount VND': totalAmountVnd,
      'Payment Method': ocr.payment_method || 'unknown',
      'Line Items JSON': JSON.stringify(lineItems),
      'Confidence': confidence,
      'Confidence Bucket': bucketConfidence(confidence),
      'Needs Manual Review': needsManualReview,
      'Manual Review Reason': ocr.manual_review_reason || '',
      'High Value': isHighValue,
      'Status': status,
      'Summary': ocr.summary_vi || '',
      'Gemini Model': source.gemini_model || '',
      'Raw OCR JSON': JSON.stringify(ocr)
    };

    const amountText = `${totalAmount.toLocaleString('vi-VN')} ${esc(currency)}`;
    const statusIcon = needsManualReview ? '⚠️' : '✅';
    const link = esc(source.web_view_link || '');

    const doneMessage = `${statusIcon} <b>Đã OCR hóa đơn</b>\n\n<b>File:</b> ${esc(source.file_name || '(không rõ)')}\n<b>Nhà cung cấp:</b> ${esc(ocr.seller_name || '(không rõ)')}\n<b>Số hóa đơn:</b> ${esc(ocr.invoice_number || '(không rõ)')}\n<b>Ngày:</b> ${esc(ocr.invoice_date || '(không rõ)')}\n<b>Tổng tiền:</b> ${amountText}\n<b>Confidence:</b> ${(confidence * 100).toFixed(0)}%\n<b>Cần kiểm tra lại:</b> ${needsManualReview ? 'Có' : 'Không'}\n\n<a href="${link}">Mở file trên Google Drive</a>`;

    const alertMessage = `🚨 <b>CẢNH BÁO HÓA ĐƠN GIÁ TRỊ LỚN</b>\n\n<b>File:</b> ${esc(source.file_name || '(không rõ)')}\n<b>Nhà cung cấp:</b> ${esc(ocr.seller_name || '(không rõ)')}\n<b>Số hóa đơn:</b> ${esc(ocr.invoice_number || '(không rõ)')}\n<b>Tổng tiền:</b> ${amountText}\n<b>Ngưỡng cảnh báo:</b> ${threshold.toLocaleString('vi-VN')} VND\n\n<a href="${link}">Mở file để duyệt</a>`;

    return {
      json: {
        ...source,
        ocr,
        line_items: lineItems,
        total_amount: totalAmount,
        total_amount_vnd: totalAmountVnd,
        confidence,
        needs_manual_review: needsManualReview,
        is_high_value: isHighValue,
        status,
        is_txn_anomaly: isTxnAnomaly,
        anomaly_row: anomalyRow,
        sheet_row: row,
        telegram_done_message: doneMessage,
        telegram_alert_message: alertMessage
      },
      pairedItem: { item: i }
    };
  } catch (error) {
    const reason = `Lỗi OCR tự động: ${error.message}`.slice(0, 500);
    const row = blankRow(source, { 'Manual Review Reason': reason });
    const link = esc(source.web_view_link || '');
    const doneMessage = `⚠️ <b>Không đọc được hóa đơn tự động</b>\n\n<b>File:</b> ${esc(source.file_name || '(không rõ)')}\n<b>Lý do:</b> ${esc(reason)}\n\n<a href="${link}">Mở file để kiểm tra thủ công</a>`;

    return {
      json: {
        ...source,
        ocr: null,
        line_items: [],
        total_amount: 0,
        total_amount_vnd: '',
        confidence: 0,
        needs_manual_review: true,
        is_high_value: false,
        status: 'ocr_failed',
        is_txn_anomaly: false,
        anomaly_row: null,
        ocr_failed: true,
        sheet_row: row,
        telegram_done_message: doneMessage,
        telegram_alert_message: ''
      },
      pairedItem: { item: i }
    };
  }
});
